import os
from glob import glob

import torch
from torch.utils.data import Dataset


class OCTDataset(Dataset):
    def __init__(self, root_dir):
        self.files = sorted(glob(os.path.join(root_dir, "*.pt")))

    def __len__(self):
        return len(self.files)

    def __getitem__(self, idx):
        sample = torch.load(
            self.files[idx],
            map_location="cpu",
            weights_only=False
        )

        x = sample["oct_bscans"].float()

        # normalize uint8 -> [0,1]
        x = x / 255.0

        # (D,H,W) -> (1,D,H,W)
        x = x.unsqueeze(0)

        y = sample["glaucoma"].long()

        return x, y

import torch
import torch.nn as nn


class Simple3DCNN(nn.Module):
    def __init__(self):
        super().__init__()

        self.features = nn.Sequential(

            nn.Conv3d(1, 16, kernel_size=3, padding=1),
            nn.BatchNorm3d(16),
            nn.ReLU(),
            nn.MaxPool3d(2),

            nn.Conv3d(16, 32, kernel_size=3, padding=1),
            nn.BatchNorm3d(32),
            nn.ReLU(),
            nn.MaxPool3d(2),

            nn.Conv3d(32, 64, kernel_size=3, padding=1),
            nn.BatchNorm3d(64),
            nn.ReLU(),
            nn.MaxPool3d(2),

            nn.Conv3d(64, 128, kernel_size=3, padding=1),
            nn.BatchNorm3d(128),
            nn.ReLU(),

            nn.AdaptiveAvgPool3d(1)
        )

        self.classifier = nn.Sequential(
            nn.Flatten(),
            nn.Linear(128, 64),
            nn.ReLU(),
            nn.Dropout(0.3),
            nn.Linear(64, 2)
        )

    def forward(self, x):
        x = self.features(x)
        x = self.classifier(x)
        return x

from torch.utils.data import DataLoader

train_ds = OCTDataset(TRAIN_DIR)
val_ds = OCTDataset(VAL_DIR)
test_ds = OCTDataset(TEST_DIR)

train_loader = DataLoader(
    train_ds,
    batch_size=2,
    shuffle=True,
    num_workers=2,
    pin_memory=True
)

val_loader = DataLoader(
    val_ds,
    batch_size=2,
    shuffle=False,
    num_workers=2
)

test_loader = DataLoader(
    test_ds,
    batch_size=2,
    shuffle=False,
    num_workers=2
)

from sklearn.metrics import accuracy_score


@torch.no_grad()
def evaluate(model, loader, device):

    model.eval()

    preds = []
    labels = []

    for x, y in loader:

        x = x.to(device)
        y = y.to(device)

        logits = model(x)

        pred = logits.argmax(1)

        preds.extend(pred.cpu().numpy())
        labels.extend(y.cpu().numpy())

    return accuracy_score(labels, preds)

import matplotlib.pyplot as plt
import torch

device = "cuda" if torch.cuda.is_available() else "cpu"

model = Simple3DCNN().to(device)

criterion = torch.nn.CrossEntropyLoss()

optimizer = torch.optim.Adam(
    model.parameters(),
    lr=1e-4
)

epochs = 30

train_losses = []
val_accs = []
test_accs = []

best_val = 0

for epoch in range(epochs):

    model.train()

    running_loss = 0

    for x, y in train_loader:

        x = x.to(device)
        y = y.to(device)

        optimizer.zero_grad()

        logits = model(x)

        loss = criterion(logits, y)

        loss.backward()

        optimizer.step()

        running_loss += loss.item()

    train_loss = running_loss / len(train_loader)

    val_acc = evaluate(
        model,
        val_loader,
        device
    )

    test_acc = evaluate(
        model,
        test_loader,
        device
    )

    train_losses.append(train_loss)
    val_accs.append(val_acc)
    test_accs.append(test_acc)

    print(
        f"Epoch {epoch+1:03d} "
        f"Loss={train_loss:.4f} "
        f"Val={val_acc:.4f} "
        f"Test={test_acc:.4f}"
    )

    if val_acc > best_val:
        best_val = val_acc

        torch.save(
            model.state_dict(),
            "best_model.pt"
        )

plt.figure(figsize=(12,5))

plt.subplot(1,2,1)
plt.plot(train_losses)
plt.title("Training Loss")
plt.xlabel("Epoch")
plt.ylabel("Loss")

plt.subplot(1,2,2)
plt.plot(val_accs, label="Val")
plt.plot(test_accs, label="Test")
plt.title("Accuracy")
plt.xlabel("Epoch")
plt.ylabel("Accuracy")
plt.legend()

plt.show()

